  "excludes.presetHint.trickplay": "Obrazy dla paska przewijania. Zaplanowane zadanie tworzy je ponownie po przywróceniu.",
  "excludes.presetHint.metadata": "Plakaty i grafiki pobrane przez aplikację. Odświeżenie metadanych pobierze je ponownie, ale są tu też obrazy przesłane przez ciebie i te zostałyby utracone. Ten wpis jest na początku wyłączony.",
