  "settings.retentionLastInfo": "Zachowuje N najnowszych kopii zapasowych, niezależnie od tego, kiedy zostały wykonane.",
  "settings.retentionDailyInfo": "Zachowuje jedną kopię zapasową dla każdego z ostatnich N dni kalendarzowych z kopią zapasową, jedną dziennie, nie N kopii.",
  "settings.retentionWeeklyInfo": "Zachowuje jedną kopię zapasową dla każdego z ostatnich N tygodni kalendarzowych z kopią zapasową.",
  "settings.retentionMonthlyInfo": "Zachowuje jedną kopię zapasową dla każdego z ostatnich N miesięcy kalendarzowych z kopią zapasową.",
  "settings.retentionYearlyInfo": "Zachowuje jedną kopię zapasową dla każdego z ostatnich N lat kalendarzowych z kopią zapasową. Gdy lat jest mniej, zachowuje też najstarszą.",
  "settings.retentionOffsiteTitle": "Przechowywanie poza siedzibą",
  "settings.retentionOffsiteHint": "Osobna polityka dla repo zdalnego, aby trzymać je dłużej jako archiwum. Wszystko 0 = zachowaj każdą kopię zdalną (bez czyszczenia zdalnego).",
  "settings.ownRetentionTitle": "Reguły przechowywania dla źródła",
  "settings.ownOffsiteRetention": "Własne reguły przechowywania kopii zdalnych",
  "settings.ownOffsiteRetentionFor": "Własne reguły przechowywania kopii zdalnych dla {source}",
  "settings.ownOffsiteRetentionHint": "Źródło może przechowywać kopie w swoim repo zdalnym według własnych reguł zamiast wspólnych reguł zdalnych powyżej. Źródło bez własnych reguł używa wspólnych.",
  "settings.ownOffsiteRetentionToggleHint": "Włączone: repo zdalne tego źródła przechowuje kopie według pięciu reguł poniżej, które zaczynają od wspólnych wartości zdalnych. Wyłączone: używa wspólnych reguł zdalnych. Wszystkie 0 zachowuje każdą kopię zdalną tego źródła.",
  "settings.retentionExtraTargets": "Dodatkowe zdalne miejsca docelowe mają własne reguły, które ustawiasz na karcie Kopia poza siedzibą każdej sekcji.",
  "settings.retentionOffsiteScope": "Te reguły dotyczą głównego zdalnego miejsca docelowego każdej sekcji, czyli adresu w jej polu kopii poza siedzibą. Każde inne zdalne miejsce docelowe, także utworzone z miejsca docelowego, zachowuje własne reguły. Jeśli są tam same zera, BombVault nigdy go nie przycina.",
  "settings.retentionCombineInfo": "Pięć reguł łączy się operatorem LUB: kopia zapasowa przetrwa, jeśli zachowałaby ją choć jedna reguła. Nie sumują się do stałej liczby. Dotyczy osobno każdego kopiowanego elementu.",

  // Off-site (rclone)
  "rclone.title": "Off-site (rclone)",
  "rclone.hint": "Wklej konfigurację rclone, aby tworzyć kopie w chmurze (Backblaze B2, S3, Google Drive, …). Jest przechowywana zaszyfrowana. SMB/NFS nie wymagają rclone: zamontuj udział w Unraid i wskaż na niego Ścieżkę kopii zapasowych.",
  "rclone.configured": "Skonfigurowane zdalne",
  "rclone.pathHint": "Następnie ustaw Ścieżkę kopii zapasowych na „rclone:<remote>:<bucket>/path”, aby wysyłać tę sekcję off-site.",
  "cloud.title": "Współdzielone dane logowania do chmury (S3 / restic REST)",
  "cloud.hint": "Poświadczenia dla zdalnych backendów restic, bez rclone. Po zapisaniu ustaw ścieżkę kopii na zdalne repo, np. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo lub sftp:user@host:/repo. Sekrety są zapisywane zaszyfrowane i nie są ponownie pokazywane.",
  "cloud.secretSet": "zapisano, zostaw puste, aby zachować",
  "cloud.storageClass.label": "Klasa pamięci off-site",
  "cloud.storageClass.default": "(domyślna dostawcy)",
  "cloud.storageClass.hint": "Dotyczy tylko natywnych backendów S3 (repozytoriów zaczynających się od s3:). Poziomy głębokiego archiwum (Glacier Flexible Retrieval, Deep Archive) celowo nie są oferowane, ponieważ psują przywracanie restic.",
  "cloud.credSets.title": "Dodatkowe zestawy poświadczeń",
  "cloud.credSets.hint": "Nadaj jednemu lub kilku zdalnym miejscom docelowym własne poświadczenia S3 lub restic REST, zamiast współdzielić powyższe.",
  "cloud.credSets.add": "Dodaj zestaw poświadczeń",
  "cloud.credSets.name": "Nazwa",
  "cloud.credSets.none": "Brak dodatkowych zestawów poświadczeń.",
  "cloud.credSets.kept": "{name} (zachowane poświadczenia)",
  "export.encrypt.hint": "Repozytoria restic są już zaszyfrowane. To opcjonalnie szyfruje jawne artefakty eksportu (tar.gz kontenera i VM wraz z ich plikami xml oraz zip flash) za pomocą age, aby można je było bezpiecznie przechowywać lub przenosić poza serwer.",
  "export.encrypt.ageInfo": "age (age-encryption.org) to małe, nowoczesne narzędzie do szyfrowania plików, prostsza alternatywa dla GPG do zapieczętowania pliku dla jednego lub wielu odbiorców.",
  "export.encrypt.enable": "Szyfruj eksporty za pomocą age",
  "export.encrypt.enableHint": "Gdy włączone, eksporty kontenera, VM i flash są pieczętowane za pomocą age przed zapisem na dysk i otrzymują przyrostek .age.",
  "export.encrypt.kitSealed": "Zestaw odzyskiwania też jest pieczętowany i trafia do Ciebie jako bombvault-recovery-kit.md.age. Pozostaje czytelnym tekstem (pancerz ASCII), więc nadal można go wkleić do menedżera haseł lub wydrukować, ale do jego otwarcia potrzebny jest Twój klucz prywatny age: przechowuj ten klucz tam, gdzie nie zależy on od samego zestawu.",
  "export.encrypt.recipients": "Odbiorcy age",
  "export.encrypt.recipientsHint": "Jeden odbiorca na wiersz. Użyj klucza publicznego age (age1...) lub klucza publicznego SSH. Do odszyfrowania poza serwerem potrzebny jest pasujący klucz prywatny. Przy włączonym szyfrowaniu i braku prawidłowego odbiorcy eksport kończy się błędem zamiast zapisać tekst jawny.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Dodaj co najmniej jednego odbiorcę age, w przeciwnym razie zaszyfrowany eksport się nie powiedzie.",
  "rclone.save": "Zapisz konfigurację",

