  "offsite.prune.title": "5 · Przycinanie zdalne",
  "offsite.prune.info": "Ten krok tylko informuje, co się dzieje, niczego nie ustawia. O tym, czy ta kopia jest przycinana, decydują append-only z kroku 4 oraz wartości zachowywania w sekcji Ustawienia, Miejsca docelowe. Aby mimo wszystko przyciąć kopię append-only, uruchom restic forget --prune po stronie magazynu, albo według własnego harmonogramu, albo stawiając na chwilę drugi serwer REST bez append-only, przycinając przez niego i wyłączając go z powrotem.",
