  "recovery.abTitle": "Import z wtyczki Appdata.Backup",
  "recovery.abIntro": "Zamienia archiwa zapisane przez wtyczkę Appdata.Backup w punkty przywracania pasujących kontenerów, każdy z datą, kiedy wtyczka go utworzyła. Archiwa są tylko odczytywane, nigdy zmieniane ani usuwane. Każde jest rozpakowywane obok repozytorium, zapisywane w kopii, a rozpakowana kopia jest potem usuwana, więc tam musi być miejsce na największe archiwum.",
