  "receiver.checkFailedHelp":
    "BombVault tylko odczytuje otrzymane repozytorium, więc go za Ciebie nie naprawi. Aby naprawić je samodzielnie, uruchom restic na powyższej lokalizacji z hasłem wyprowadzonym z APP_KEY instancji wysyłającej, które znajduje się w zestawie odzyskiwania tamtej instancji, a nie tej maszyny. Spróbuj najpierw `restic repair index`, a potem `restic repair snapshots`, jeśli migawki nadal są nieczytelne.",
  "receiver.lastChecked": "Sprawdzono {time}",
  "receiver.server.title": "Serwer odbiorczy",
  "receiver.server.tip": "rest-server w trybie append-only na tej maszynie. Pozostałe instancje w twojej grupie mogą kopiować do niego swoje kopie zewnętrzne, a nawet ten, kto ma ich login, nie może usunąć tego, co dotarło.",
  "receiver.server.intro": "Pozwól partnerom kopiować swoje kopie zewnętrzne na tę maszynę. BombVault uruchamia tu rest-server w trybie append-only i oferuje go instancjom w twojej grupie.",
  "receiver.server.setUp": "Skonfiguruj serwer odbiorczy",
