  "anomaly.settings.title": "Anomalie",
  "anomaly.settings.hint": "Porównuje każdą kopię elementu z jego własną historią i zgłasza to, co nie pasuje. Działa w tle po każdej kopii i żadnej nie spowalnia. Większość kontroli zaczyna się po 10 kopiach elementu; błędy, nadpisanie większości danych i prawie puste źródło są sprawdzane od początku. Wolne miejsce jest pilnowane w lokalnych repozytoriach i w repozytoriach rclone, które je podają; na udziale użytkownika Unraid to wolne miejsce całej macierzy.",
  "anomaly.settings.toggle": "Wykrywaj anomalie",
  "anomaly.settings.sensitivity": "Czułość",
  "anomaly.settings.sensitivityHint": "Surowa zgłasza też mniejsze zmiany, Łagodna tylko duże, Zrównoważona pasuje do większości serwerów. Każdy wpis może mieć własne ustawienie w Anomalie, Monitorowanie.",
  "anomaly.settings.notifyMin": "Wysyłaj powiadomienie dla",
  "anomaly.settings.notifyHint": "Korzysta z kanałów ustawionych w Powiadomienia. Każdy wpis może to zmienić w Anomalie, Monitorowanie. Powtarzające się błędy kopii i zrzutów oraz nieudane zaplanowane kontrole przywracania wysyłają już własną wiadomość, więc nie są wysyłane drugi raz.",
  "anomaly.settings.notifyMuted": "Teraz nic nie jest wysyłane: powiadomienia są wyłączone albo nie ustawiono żadnego kanału.",
  "anomaly.settings.openNotifications": "Otwórz ustawienia powiadomień",
  "anomaly.settings.holdToggle": "Zachowuj stare kopie, gdy źródło mocno się kurczy lub zostaje nadpisane",
  "anomaly.settings.holdHint": "Trzy znaleziska wstrzymują usuwanie starych kopii: źródło, które nagle jest prawie puste, źródło, które stało się dużo mniejsze, i kopia, która ponownie zapisała większość danych, jak wygląda ransomware. Inaczej retencja usuwałaby dobre starsze kopie jedną po drugiej. Dopóki taka anomalia jest otwarta, zachowywane są stare kopie tylko tego elementu (albo tego zrzutu bazy danych lub zbioru danych ZFS); wszystko inne jest czyszczone jak zwykle. Potwierdź anomalię lub oznacz ją jako oczekiwaną, aby wznowić.",
