  "whatsNew.overviewHead": "Zielone punkty oznaczają nowości. Kliknięcie ukrywa punkt, a wszystkie znajdziesz w sekcji Ustawienia, Info.",
  "whatsNew.overviewCustomize": "Przegląd zaczyna się od pięciu kart. Więcej czeka pod „Dostosuj”, a każdą kartę można przesunąć, zmienić jej rozmiar i ukryć.",
  "whatsNew.overviewDecline": "„Nie kopiuj” zdejmuje pozycję z tej listy, gdy pomijasz ją celowo. Przestaje się wtedy liczyć jako niechroniona.",
