  "whatsNew.backupsRow": "Wiersz pokazuje jeden status, a resztę ma w dymku obok nazwy. Wiersze zaznaczasz jak pliki: Ctrl+kliknięcie, Shift+kliknięcie albo długie naciśnięcie.",
  "whatsNew.backupsActions": "Główna akcja strony unosi się w prawym dolnym rogu. „Więcej” skrywa te rzadkie.",
  "whatsNew.entryPage": "Każdy wpis ma własną stronę z trzema zakładkami: Kopie zapasowe, Ustawienia i Weryfikacja.",
  "whatsNew.entryDefaults": "Pozycja stosuje domyślny harmonogram i miejsce docelowe, dopóki nie dostanie tu własnych.",
  "whatsNew.restoreTiles": "„Przywracanie” to jedna strona do wszystkiego. Wybierz sekcję albo wyszukaj pozycję, a potem wybierz kopię zapasową na jej osi czasu.",
  "whatsNew.restoreWhere": "Jedno okno pyta, co przywrócić i dokąd. „Obok oryginału” przywraca kopię, a oryginał zostawia, jak jest.",
  "whatsNew.restoreMany": "Wybierz kilka pozycji przez Ctrl+klik, Shift+klik albo długie przytrzymanie i przywróć je razem, jedna po drugiej.",
  "whatsNew.restoreEmergency": "Tu zaczyna się kreator awaryjny. W czterech krokach przywraca serwer, którego już nie ma albo który postawiono od nowa.",
  "whatsNew.anomaliesTiles": "Kafelki wybierają ważność. „Otwarta” lub „Zamknięta” wybiera listę.",
  "whatsNew.anomaliesRings": "Pierścień przy każdej pozycji pokazuje, jak daleko wykrywanie nauczyło się, co jest normalne.",
  "whatsNew.storageList": "Lokalne i zdalne miejsca docelowe są na jednej liście. Każde miejsce docelowe ma własną stronę.",
  "whatsNew.storageFlow": "3-2-1 jako obraz. Każda linia od sekcji do miejsca docelowego to przełącznik.",
  "whatsNew.locationKeep": "Przechowywanie to „Krótko”, „Zrównoważone”, „Długo” albo twoje własne wartości. Oś czasu pokazuje, które kopie zapasowe zachowuje reguła.",
  "whatsNew.locationMove": "„Przenieś” zabiera kopię sekcji do innego miejsca docelowego razem z całą historią.",
  "whatsNew.instancesPair": "Instancje paruje się dwunastoma słowami. Potem każda pokazuje swoje role jako kafelki.",
  "whatsNew.settingsTiles": "Ustawienia to czternaście kafelków. Naciśnij / albo Ctrl+K, żeby przeszukać je wszystkie, także po dawnych nazwach stron.",
  "whatsNew.settingsPin": "Miejsca docelowe i Instancje to kafelki ustawień. Ten przełącznik przypina je do panelu bocznego.",
